import { bootstrapApplication } from '@angular/platform-browser';
import { AppComponent } from './app/app.component';

// ❌ OLD: Without hydration, the client re-renders the app from
// scratch: Angular creates a fresh DOM tree and replaces the SSR
// markup. Users see flicker, lose scroll position and focus, and the
// SSR work is wasted (double render).
bootstrapApplication(AppComponent);

// The SSR HTML is discarded and rebuilt client-side, which also
// defeats some benefits of server rendering (faster interaction is
// delayed until the client render completes).

import { bootstrapApplication } from '@angular/platform-browser';
import { provideClientHydration, withEventReplay } from '@angular/platform-browser';
import { AppComponent } from './app/app.component';

// ✅ NEW: The client adopts the SSR DOM instead of re-creating it, and
// events dispatched before hydration completes are replayed.
bootstrapApplication(AppComponent, {
  providers: [
    provideClientHydration(withEventReplay()), // ✅ NEW: reuse DOM + replay events
  ],
});

// Result: no flicker, scroll/focus preserved, and a click on a
// server-rendered button just before hydration is not lost — it is
// replayed once the app is interactive.
